package com.enterprisehub.service;
import com.enterprisehub.domain.*; import com.enterprisehub.repo.*; import java.time.Instant; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component public class DemoData implements CommandLineRunner { private final DepartmentRepository departments; private final EmployeeRepository employees; private final ServiceRequestRepository requests; private final PasswordEncoder encoder; public DemoData(DepartmentRepository d,EmployeeRepository e,ServiceRequestRepository r,PasswordEncoder p){departments=d;employees=e;requests=r;encoder=p;} public void run(String...args){if(!departments.findAll().isEmpty())return;var it=departments.save(new Department("Information Technology","IT"));var ops=departments.save(new Department("Operations","OPS"));var people=departments.save(new Department("People & Culture","PEOPLE"));var admin=employees.save(new Employee("Alex Morgan","admin@enterprisehub.demo",encoder.encode("Password123!"),"ADMIN",it));var manager=employees.save(new Employee("Jordan Lee","manager@enterprisehub.demo",encoder.encode("Password123!"),"MANAGER",ops));var employee=employees.save(new Employee("Taylor Smith","employee@enterprisehub.demo",encoder.encode("Password123!"),"EMPLOYEE",people));seed("Laptop replacement request","Current device is approaching end of life and battery health is below 60%.","IT & Equipment","HIGH","PENDING_APPROVAL",employee,it,null,2);seed("Access to analytics workspace","Need read access to the quarterly service performance workspace.","Access","MEDIUM","OPEN",employee,it,manager,5);seed("Conference room display issue","The display in Cedar room does not detect HDMI input.","Facilities","LOW","IN_PROGRESS",manager,ops,admin,1);seed("New starter onboarding","Prepare accounts and equipment for a new team member starting next week.","People","MEDIUM","RESOLVED",manager,people,employee,9);seed("VPN connection drops","VPN disconnects every 20 minutes while working remotely.","IT & Equipment","URGENT","OPEN",employee,it,admin,0);}
private void seed(String t,String desc,String cat,String pri,String status,Employee requester,Department dep,Employee assigned,int days){var r=new ServiceRequest();r.title=t;r.description=desc;r.category=cat;r.priority=switch(pri){case "URGENT"->"P1";case "HIGH"->"P2";case "MEDIUM"->"P3";default->"P4";};r.impact=switch(r.priority){case "P1"->"CRITICAL";case "P2"->"HIGH";case "P3"->"MEDIUM";default->"LOW";};r.urgency=r.impact;r.priorityReason="Seeded demo priority from "+r.impact.toLowerCase()+" impact and urgency";r.status=status;r.requester=requester;r.department=dep;r.assignee=assigned;r.slaDueAt=Instant.now().plusSeconds(com.enterprisehub.service.RequestService.slaSeconds(r.priority));r.dueAt=r.slaDueAt;if(status.equals("RESOLVED")){r.resolvedAt=Instant.now().minusSeconds(3600);r.resolutionSeconds=3600L;r.resolvedOnTime=true;}requests.save(r);} }
